function lineAccuracy(expected, said) {
  const w = (x) => String(x || "").toLowerCase().replace(/[’']/g, "").replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter(Boolean);
  const a = w(expected).slice(0, 600),
    b = w(said).slice(0, 600);
  if (!a.length) return 100;
  if (!b.length) return 0;
  const dp = new Array(b.length + 1).fill(0);
  for (let i = 1; i <= a.length; i++) {
    let prev = 0;
    for (let j = 1; j <= b.length; j++) {
      const tmp = dp[j];
      dp[j] = a[i - 1] === b[j - 1] ? prev + 1 : Math.max(dp[j], dp[j - 1]);
      prev = tmp;
    }
  }
  return Math.round((200 * dp[b.length]) / (a.length + b.length));
}
const titleCase = (n) => String(n || "").toLowerCase().replace(/(^|[\s'-])\p{L}/gu, (m) => m.toUpperCase());
function deriveTopic(s, T, figure) {
  if (T.topic) return T.topic;
  const cut = (x) => String(x).slice(0, 300);
  switch (s.id) {
    case "thesis":
      return cut(T.thesisStatement ? `Thesis: ${T.thesisStatement}${T.field ? ` (${T.field})` : ""}` : "Thesis defense");
    case "acting":
      return cut(T.yourRole ? `Acting: ${T.yourRole}${T.sceneContext ? ` — ${T.sceneContext}` : ""}` : "Acting rehearsal");
    case "interview":
      return cut(T.jobTitle ? `Interview: ${T.jobTitle}${T.company ? ` at ${T.company}` : ""}` : "Job interview");
    case "negotiation":
      return cut(T.scenario || T.yourGoal ? `Negotiation: ${T.scenario || T.yourGoal}` : "Negotiation practice");
    case "sales":
      return cut(T.product ? `Pitch: ${T.product}${T.buyerPersona ? ` to ${T.buyerPersona}` : ""}` : "Sales roleplay");
    case "difficult":
      return cut(T.situation || "Difficult conversation");
    case "historical":
      return cut(figure?.suggestedTopic || (figure ? `Debate with ${figure.name}` : "Historical debate"));
    case "rapbattle":
      return cut(T.theme ? `Rap battle: ${T.theme}` : "Open rap battle");
    case "witness":
      return cut(T.who ? `Sharing the gospel with ${T.who}` : "Sharing the gospel");
    case "trafficstop":
      return cut(`Traffic stop: ${{ nervous: "nervous driver", argumentative: "argumentative driver", sovereign: "sovereign citizen", impaired: "possibly impaired driver", ccw: "driver with a firearm" }[T.driver] || "driver"}`);
    case "deescalate":
      return cut({ mental: "Crisis call: mental health", refuse: "Crisis call: refusing to leave", intox: "Crisis call: intoxicated", domestic: "Crisis call: domestic", selfharm: "Crisis call: overpass" }[T.call] || "Crisis call");
    case "testify":
      return cut(`Cross-examination: ${T.caseFacts || "the case"}`);
    case "speaking":
      return cut(`Talk: ${T.topic || "public speaking"}`);
    case "salary":
      return cut(`${{ offer: "Job offer", raise: "Raise", promotion: "Promotion", counter: "Counter-offer" }[T.kind] || "Pay"}: ${T.role || "negotiation"}`);
    case "customer":
      return cut(`Angry customer: ${T.complaint || T.role || "complaint"}`);
    case "auditor":
      return cut({ lobby: "Audit: station lobby", sidewalk: "Audit: from the sidewalk", postoffice: "Audit: post office", complaint: "Audit: filming a business", scene: "Audit: near an active scene" }[T.scenario] || "First Amendment audit");
    case "rights":
      return cut({ traffic: "Traffic stop", dui: "Late-night stop", walking: "Stopped on the street", passenger: "Passenger in a stopped car", door: "Officers at the door" }[T.scenario] || "Police stop");
    case "expert":
      return cut(T.profession ? `Expert: ${T.profession}` : "Domain expert");
    default:
      return cut((s.name || "Sparring") + " session");
  }
}
function showCoinTossModal(prm, oppName) {
  return new Promise((res, rej) => {
    const m = document.createElement("div");
    m.className = "fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4 backdrop-blur-md animate-fade-in";
    m.setAttribute("role", "dialog");
    m.setAttribute("aria-modal", "true");
    m.innerHTML = `<div class="relative w-full max-w-sm overflow-hidden rounded-3xl border border-ink-700 bg-ink-900 p-7 text-center shadow-2xl">
      <p class="eyebrow mb-5 !text-amber-400">Coin toss</p>
      <div class="coin-container my-6"><div class="coin-3d coin-flipping" id="toss-coin">
        <div class="coin-side coin-side-front"><span class="text-[11px] font-black uppercase tracking-wider">You</span></div>
        <div class="coin-side coin-side-back"><span class="text-[11px] font-black uppercase tracking-wider">Them</span></div>
      </div></div>
      <div id="toss-status" class="mb-1.5 text-base font-semibold text-white">Flipping…</div>
      <p id="toss-sub" class="text-sm text-slate-400">Heads you open · Tails they open</p>
      <button type="button" id="toss-go" class="btn-primary mt-6 hidden w-full py-3">Enter the floor →</button>
    </div>`;
    document.body.appendChild(m);
    const coin = m.querySelector("#toss-coin"),
      status = m.querySelector("#toss-status"),
      sub = m.querySelector("#toss-sub"),
      go = m.querySelector("#toss-go");
    prm
      .then((data) => {
        setTimeout(() => {
          coin.classList.remove("coin-flipping");
          const you = data.resolvedFirstSpeaker === "user";
          coin.classList.add(you ? "coin-land-heads" : "coin-land-tails");
          status.innerHTML = you ? '<span class="text-emerald-400">Heads — you open.</span>' : `<span class="text-amber-400">Tails — ${xt(oppName)} opens.</span>`;
          sub.textContent = you ? "Deliver your opening statement." : `${oppName} takes the floor first.`;
          go.classList.remove("hidden");
          go.focus();
          const tm = setTimeout(() => {
            m.remove();
            res(data);
          }, 2200);
          go.onclick = () => {
            clearTimeout(tm);
            m.remove();
            res(data);
          };
        }, 1200);
      })
      .catch((err) => {
        m.remove();
        rej(err);
      });
  });
}
